import numpy as np

class XGaze_2D_Sampler:
    def __init__(self, D, n_valid_cam=None, side=None, split='train'):
        # D is a dict generated by xgaze_data (e.g. double_eye_val.npy)
        self.D = D
        self.n = len(D['id'])
        self.n_bins_pitch = D['pitch_nbins']
        self.n_bins_yaw = D['yaw_nbins']
        self.split = split

        self.threshold = 2 # +- threshold in N(0,1)
        self.bins = []
        for i in range(self.n_bins_pitch):
            self.bins.append([])
            for j in range(self.n_bins_yaw):
                self.bins[i].append([])
        self.actual_bin_pop = np.zeros((self.n_bins_pitch, self.n_bins_yaw), int)

        self.id_list = []
        for i in range(self.n):
            if n_valid_cam and D['cam_cid'][i]>=n_valid_cam:
                continue
            if split == 'val' and (D['pitch_cid'][i] == 0 or D['pitch_cid'][i] == self.n_bins_pitch - 1 or \
                                   D['yaw_cid'][i] == 0 or D['yaw_cid'][i] == self.n_bins_yaw - 1):  # only val mode skips first and last bin
                continue
            if side and D['side'][i] != side:
                continue
            self.id_list.append(i)
            pitch = D['pitch_cid'][i]
            yaw = D['yaw_cid'][i]
            self.bins[pitch][yaw].append(i)
            self.actual_bin_pop[pitch, yaw] += 1

        self.population = len(self.id_list)
        self.quote_bin_pop = self.bin_quote()

    def plot_histogram(self):
        import matplotlib.pyplot as plt
        M = np.amax(self.actual_bin_pop)
        plt.imshow(self.actual_bin_pop / M)
        plt.show()

    def _freq_1d(self, n_bins):
        import scipy.stats as S
        cdf = S.norm.cdf
        interval = self.threshold * 2 / n_bins

        bins = [0 for _ in range(n_bins)]
        it = range(1, n_bins - 1) if self.split == 'val' else range(n_bins)

        for i in it:
            x1 = -self.threshold + interval*i
            x2 = -self.threshold + interval*(i+1)
            bins[i] = (cdf(x2) - cdf(x1))
        return bins

    def bin_quote(self):
        # get histogram (actual bin sizes) & ideal bin sizes

        # |x|+|y|
        # freq_pitch = self._freq_1d(self.n_bins_pitch)
        # freq_yaw = self._freq_1d(self.n_bins_yaw)
        #
        # freq = np.dot(np.array(freq_pitch).reshape((self.n_bins_pitch, 1)),
        #               np.array(freq_yaw).reshape((1, self.n_bins_yaw)))
        # freq = freq / np.sum(freq) * self.population

        # max(x,y)
        import scipy.stats as S
        pdf = S.norm.pdf
        freq = np.zeros((self.n_bins_pitch, self.n_bins_yaw))

        n_half_pitch = self.n_bins_pitch // 2
        n_half_yaw = self.n_bins_yaw // 2

        for i in range(self.n_bins_pitch):
            for j in range(self.n_bins_yaw):
                if i==0 or i==self.n_bins_pitch-1 or j==0 or j==self.n_bins_yaw-1:
                    freq[i,j] = 0.01
                else:
                    freq[i,j] = pdf(max(np.abs(i - n_half_pitch) / n_half_pitch,
                        np.abs(j - n_half_yaw) / n_half_yaw) * self.threshold)

        freq = freq / np.sum(freq) * self.population

        return freq.astype(int)

    def sample(self):
        # create a ID list whose distribution fits +-2 ~ N(0,1)
        new_id_list = []
        for pitch in range(self.n_bins_pitch):
            for yaw in range(self.n_bins_yaw):
                if self.quote_bin_pop[pitch, yaw]==0:
                    continue
                n_repeat = self.quote_bin_pop[pitch, yaw] // self.actual_bin_pop[pitch, yaw]
                n_tail = self.quote_bin_pop[pitch, yaw] % self.actual_bin_pop[pitch, yaw]
                sampled_bin = []
                for i in range(n_repeat):
                    sampled_bin = np.append(sampled_bin, self.bins[pitch][yaw])
                sampled_bin = np.append(sampled_bin,
                                        np.random.permutation(self.bins[pitch][yaw])[:n_tail])
                new_id_list = np.append(new_id_list, sampled_bin)
        return np.random.permutation(new_id_list).astype(int)